pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Synth} from "../src/Synth.sol";

contract InvMutTest is Test {
    Synth c;
    function setUp() public { c = new Synth(address(this), address(new __InvMutHandleStub())); }

    function testFuzz_property(address spender, uint256 subtractedValue) public {
        vm.assume(spender != address(0));
        vm.assume(subtractedValue > 0);

        c.approve(spender, subtractedValue);

        bool ok;
        try c.decreaseAllowance(spender, subtractedValue) returns (bool ret) {
            ok = ret;
        } catch {
            ok = false;
        }

        assertTrue(ok && c.allowance(address(this), spender) == 0);
    }
}

